function slugify(tekst) {
  // Leerwoordverwijdering met een koppelteken als delimiter
  const words = tekst.split(' ');

  // Filter op leestekens en vervang ze door één koppelteken
  const cleanedWords = words.map(word => word.replace(/[^a-zA-Z0-9]/g, '').trim());

  // Sorteren van de resterende woorden naar alfabetisch
  const sortedWords = cleanedWords.sort();

  // Maak een array met alleen de eerste en laatste woord
  const slug = sortedWords[0] + '-' + sortedWords[sortedWords.length - 1];

  return slug;
}

