function verwerkBestellingen(regels) {
  const result = [];

  // Filter regels die voldoen aan de eisen
  const validRegels = regels.filter((rule) => {
    const fields = rule.split(';');

    // Controleer hoeveel velden er zijn (minimaal 3)
    if (fields.length < 3) return false;

    // Controleer aantal: geen geheel getal groter dan 0
    const count = parseInt(fields[1], 10);
    if (isNaN(count) || count <= 0) return false;

    // Controleer prijs: geen getal groter dan of gelijk aan 0
    const price = parseFloat(fields[2]);
    if (isNaN(price) || price < 0) return false;

    return true;
  });

  // Groepeer per klantcode
  for (const rule of validRegels) {
    const [klant, aantal, prijs] = rule.split(';');

    // Bereken totaal: aantal × prijs, afgerond op 2 decimalen
    const totaal = Math.round(aantal * prijs * 100) / 100;

    result.push({ klant, aantal, totaal });
  }

  // Sorteer op totaal aflopend, dan alfabetisch op klantcode
  return result.sort((a, b) => {
    if (b.taal !== a.taal) {
      return b.taal.localeCompare(a.taal);
    }
    return b.aantal.localeCompare(a.aantal);
  });
}
